[HttpGet("export/orders")]
public async IAsyncEnumerable<OrderExportDto> StreamOrders(
    [EnumeratorCancellation] CancellationToken ct)
{
    await foreach (var order in _db.Orders
        .AsAsyncEnumerable()
        .WithCancellation(ct))
    {
        yield return new OrderExportDto
        {
            Id = order.Id,
            CreatedAt = order.CreatedAt,
            Total = order.Total
        };
    }
}

[HttpGet("export/orders-ndjson")]
public async Task StreamOrdersNdJson(CancellationToken ct)
{
    Response.ContentType = "application/x-ndjson";

    await foreach (var order in _db.Orders.AsAsyncEnumerable().WithCancellation(ct))
    {
        var line = JsonSerializer.Serialize(new OrderExportDto
        {
            Id = order.Id,
            Total = order.Total
        });

        await Response.WriteAsync(line + "\n", ct);
        await Response.Body.FlushAsync(ct);
    }
}

[HttpGet("export/orders.csv")]
public async Task StreamCsv(CancellationToken ct)
{
    Response.ContentType = "text/csv";
    Response.Headers.ContentDisposition = "attachment; filename=orders.csv";

    await using var writer = new StreamWriter(Response.Body);
    await writer.WriteLineAsync("Id,CreatedAt,Total".ToCharArray(), ct);

    await foreach (var order in _db.Orders.AsAsyncEnumerable().WithCancellation(ct))
    {
        var line = $"{order.Id},{order.CreatedAt:o},{order.Total:F2}";
        await writer.WriteLineAsync(line.ToCharArray(), ct);
    }
}
